INSERT INTO "LegalSource" ("code","title","publication","publishedAt","effectiveFrom","subject","articles","url","verificationStatus","notes","article","state","summary","lastAmendment","lastCheckedAt","components","evidence","history","updatedAt") VALUES ('WLB-1981','Wet Loonbelasting','S.B. 1981 no. 181 (geldende tekst S.B. 1985 no. 10, zoals laatstelijk gewijzigd)',NULL,NULL,'Loonbelasting — basiswet (inhoudingsplicht werkgever, zuiver loon, belastbaar loon, tarieven, art. 18a delegatie)','[{"article":"6","summary":"Werkgever is inhoudingsplichtige"},{"article":"18a","summary":"Bedragen en percentages van o.a. art. 10, 12, 13, 14, 17 en 17c kunnen bij staatsbesluit worden gewijzigd"}]'::jsonb,'https://www.sris.sr/wp-content/uploads/2018/01/Wet-Loonbelasting.pdf','PENDING_VERIFICATION',NULL,'art. 6, 10, 12, 13, 14, 17, 17a, 18a','AMENDED','De werkgever houdt loonbelasting in en draagt af. Bedragen en percentages (o.a. art. 10, 12, 13, 14, 17 en 17c) worden bij staatsbesluit op grond van art. 18a vastgesteld.','S.B. 2025 no. 129 (staatsbesluit ter uitvoering van art. 18a)','2026-11-03','["Loonbelasting (LB)","Beroepskostenaftrek","Belastingvrije som","Tariefschijven","Overwerk (LB-OT)","Bijzondere beloningen (LB-BB)","Kinderbijslag (vrijstelling)"]'::jsonb,'[{"source":"SRIS — Wet Loonbelasting (geconsolideerde tekst)","url":"https://www.sris.sr/wp-content/uploads/2018/01/Wet-Loonbelasting.pdf","kind":"OFFICIAL_EXCERPT","finding":"Basiswet beschikbaar; volledige tekst niet ingezien vanuit de onderzoeksomgeving.","checkedAt":"2026-11-03"}]'::jsonb,'[{"date":"2026-11-03","previous":"URL belastingdienst.sr/…/Wet-Loonbelasting.pdf","current":"URL sris.sr/…/Wet-Loonbelasting.pdf","reason":"Stichting Rechtsorde Suriname (SRIS) publiceert de Staatsbladen; beide links verwijzen naar dezelfde wet."}]'::jsonb,NOW()) ON CONFLICT ("code") DO UPDATE SET "title"=EXCLUDED."title","publication"=EXCLUDED."publication","publishedAt"=EXCLUDED."publishedAt","effectiveFrom"=EXCLUDED."effectiveFrom","subject"=EXCLUDED."subject","articles"=EXCLUDED."articles","url"=EXCLUDED."url","verificationStatus"=EXCLUDED."verificationStatus","notes"=EXCLUDED."notes","article"=EXCLUDED."article","state"=EXCLUDED."state","summary"=EXCLUDED."summary","lastAmendment"=EXCLUDED."lastAmendment","lastCheckedAt"=EXCLUDED."lastCheckedAt","components"=EXCLUDED."components","evidence"=EXCLUDED."evidence","history"="LegalSource"."history" || EXCLUDED."history","updatedAt"=NOW();
INSERT INTO "LegalSource" ("code","title","publication","publishedAt","effectiveFrom","subject","articles","url","verificationStatus","notes","article","state","summary","lastAmendment","lastCheckedAt","components","evidence","history","updatedAt") VALUES ('SB-2022-149','Wet van 30 december 2022 houdende nadere wijziging van de Wet Loonbelasting','S.B. 2022 no. 149','2022-12-30',NULL,'Verwerking van de heffingskorting in de belastingvrije som; verhoging vrijstelling vakantietoelage','[{"article":"—","summary":"Heffingskorting opgenomen in de belastingvrije som (geen afzonderlijke heffingskorting meer)"},{"article":"—","summary":"Vrijstelling vakantietoelage SRD 6.516 (inmiddels vervangen door latere staatsbesluiten)"}]'::jsonb,'https://www.sris.sr/wp-content/uploads/2023/01/S.B.-2022-no.-149-wijziging-van-de-Wet-Loonbelasting.pdf','PENDING_VERIFICATION','Inhoud alleen via secundaire samenvatting bevestigd; volledige tekst nalezen.','diverse artikelen','AMENDED','Heffingskorting opgenomen in de belastingvrije som. Vrijstelling vakantietoelage destijds verhoogd naar SRD 6.516 — later opnieuw gewijzigd.','S.B. 2024 no. 2; S.B. 2025 no. 101 / no. 129','2026-11-03','["Belastingvrije som","Bijzondere beloningen (vakantietoelage)"]'::jsonb,'[{"source":"Zoekresultaat SRIS (S.B. 2022 no. 149)","url":"https://www.sris.sr/wp-content/uploads/2023/01/S.B.-2022-no.-149-wijziging-van-de-Wet-Loonbelasting.pdf","kind":"OFFICIAL_EXCERPT","finding":"Verhoging vrijstelling vakantietoelage naar SRD 6.516.","checkedAt":"2026-11-03"}]'::jsonb,'[]'::jsonb,NOW()) ON CONFLICT ("code") DO UPDATE SET "title"=EXCLUDED."title","publication"=EXCLUDED."publication","publishedAt"=EXCLUDED."publishedAt","effectiveFrom"=EXCLUDED."effectiveFrom","subject"=EXCLUDED."subject","articles"=EXCLUDED."articles","url"=EXCLUDED."url","verificationStatus"=EXCLUDED."verificationStatus","notes"=EXCLUDED."notes","article"=EXCLUDED."article","state"=EXCLUDED."state","summary"=EXCLUDED."summary","lastAmendment"=EXCLUDED."lastAmendment","lastCheckedAt"=EXCLUDED."lastCheckedAt","components"=EXCLUDED."components","evidence"=EXCLUDED."evidence","history"="LegalSource"."history" || EXCLUDED."history","updatedAt"=NOW();
INSERT INTO "LegalSource" ("code","title","publication","publishedAt","effectiveFrom","subject","articles","url","verificationStatus","notes","article","state","summary","lastAmendment","lastCheckedAt","components","evidence","history","updatedAt") VALUES ('SB-2024-2','Staatsbesluit ter uitvoering van artikel 18a van de Wet Loonbelasting','S.B. 2024 no. 2','2024-01-11','2024-01-01','Beroepskostenaftrek, belastingvrije som en tariefschijven loonbelasting','[{"article":"12","summary":"Beroepskostenaftrek SRD 4.800 per jaar (SRD 400 per maand)"},{"article":"13","summary":"Belastingvrije som SRD 108.000 per jaar (SRD 9.000 per maand)"},{"article":"14","summary":"Tarief: 8% tot SRD 42.000; 18% tot SRD 84.000; 28% tot SRD 126.000; 38% daarboven"},{"article":"17a lid 2","summary":"Afzonderlijke tariefstructuur: 5% / 15% / 25% / 35% (zelfde schijfgrenzen). Toepassingsbereik nog te verifiëren"}]'::jsonb,'https://www.sris.sr/wp-content/uploads/2024/01/S.B.-2024-no.-2-STAATSBESLUIT-11-januari-2024-uitvoeringartikel-18a-Wet-Loonbelasting-S.B.-1981-no.-181-laatstelijk-gewijzigd-S.B.pdf','PARTIALLY_VERIFIED','Primaire tekst aangeleverd door ARA Intelligent Solutions; belastingvrije som van SRD 9.000 per maand vanaf 1 januari 2024 bevestigd in meerdere publicaties. Art. 17a: toepassingsbereik niet geverifieerd (afzonderlijk regime, niet automatisch toegepast).','art. 12, 13, 14, 17a lid 2','AMENDED','Beroepskostenaftrek SRD 4.800 per jaar; belastingvrije som SRD 108.000 per jaar (SRD 9.000 per maand); tarief 8% / 18% / 28% / 38% met schijven van SRD 42.000. Geen wijziging van deze bedragen voor 2026 gevonden.','S.B. 2025 no. 101 / no. 129 (bijzondere beloningen en overwerk; art. 12–14 volgens gevonden bronnen ongewijzigd)','2026-11-03','["Beroepskostenaftrek","Belastingvrije som","Tariefschijven art. 14","Regime art. 17a (niet actief)"]'::jsonb,'[{"source":"VSB — Nieuwe maatregelen in de loonbelasting (2024)","url":"https://vsbstia.org/?p=9005","kind":"SECONDARY","finding":"Belastingvrije som per 1 januari 2024 verhoogd naar SRD 9.000 per maand.","checkedAt":"2026-11-03"},{"source":"Celery — Belastingen en sociale premies 2026","url":"https://www.celerypayroll.com/blog/algemeen/belastingen-en-sociale-premies-2026/","kind":"SECONDARY","finding":"Voor 2026 geen wijzigingen van de loonbelastingtabel ten opzichte van 2025 bekend (bron mogelijk verouderd).","checkedAt":"2026-11-03"}]'::jsonb,'[]'::jsonb,NOW()) ON CONFLICT ("code") DO UPDATE SET "title"=EXCLUDED."title","publication"=EXCLUDED."publication","publishedAt"=EXCLUDED."publishedAt","effectiveFrom"=EXCLUDED."effectiveFrom","subject"=EXCLUDED."subject","articles"=EXCLUDED."articles","url"=EXCLUDED."url","verificationStatus"=EXCLUDED."verificationStatus","notes"=EXCLUDED."notes","article"=EXCLUDED."article","state"=EXCLUDED."state","summary"=EXCLUDED."summary","lastAmendment"=EXCLUDED."lastAmendment","lastCheckedAt"=EXCLUDED."lastCheckedAt","components"=EXCLUDED."components","evidence"=EXCLUDED."evidence","history"="LegalSource"."history" || EXCLUDED."history","updatedAt"=NOW();
INSERT INTO "LegalSource" ("code","title","publication","publishedAt","effectiveFrom","subject","articles","url","verificationStatus","notes","article","state","summary","lastAmendment","lastCheckedAt","components","evidence","history","updatedAt") VALUES ('SB-2025-101','Staatsbesluit van 22 juli 2025 ter uitvoering van artikel 18a van de Wet Loonbelasting','S.B. 2025 no. 101','2025-07-22','2025-07-22','Vrijstelling bijzondere beloningen (vakantietoelage, gratificatie, bonus) en tariefschijven overwerk','[{"article":"—","summary":"Vrijstelling bijzondere beloningen SRD 19.500 per jaar, terugwerkend tot 1 januari 2025"},{"article":"—","summary":"Overwerk: 5% tot SRD 2.500; 15% SRD 2.500–7.500; 25% boven SRD 7.500 (per maand), vanaf 1 juli 2025"}]'::jsonb,'https://www.sris.sr/wp-content/uploads/2025/07/S.B.-2025-no.-101-STAATSBESLUIT-van-22-juli-2025-ter-uitvoering-van-artikel-18a-van-de-Wet-Loonbelasting.pdf','CONFLICT','Inhoud consistent in meerdere bronnen, maar de verhouding tot S.B. 2025 no. 129 (zelfde onderwerp, 29 oktober 2025) is niet vastgesteld. ARA Payroll gebruikt nog SRD 10.016 als vrijstelling bijzondere beloningen: beheerder moet na verificatie een nieuwe regelset-versie vaststellen.','art. 17 (bijzondere beloningen), art. 17c (overwerk) — artikelnummers nog te bevestigen','TO_VERIFY','Vrijstelling bijzondere beloningen van SRD 10.016 naar SRD 19.500 per jaar (terugwerkend tot 1 januari 2025); overwerk 5% tot SRD 2.500, 15% van SRD 2.500 tot SRD 7.500 en 25% daarboven (terugwerkend tot 1 juli 2025).',NULL,'2026-11-03','["Bijzondere beloningen (LB-BB): vrijstelling","Overwerk (LB-OT): schijven"]'::jsonb,'[{"source":"HBN Law & Tax — Loonbelastingwijzigingen per Staatsbesluit 22 juli 2025","url":"https://hbnlawtax.com/tax-instant-news/suriname-loonbelastingwijzigingen-per-staatsbesluit-22-juli-2025/","kind":"SECONDARY","finding":"Vrijstelling SRD 10.016 → SRD 19.500 per jaar (terugwerkend tot 1-1-2025); overwerkschijven 5/15/25% (vanaf 1-7-2025).","checkedAt":"2026-11-03"},{"source":"Starnieuws — Hogere belastingvrije som voor overuren en vakantiegeld","url":"https://www.starnieuws.com/index.php/welcome/index/nieuwsitem/87481","kind":"SECONDARY","finding":"Bevestigt verhoging vrijstelling vakantiegeld/bonussen en nieuwe overwerkschijven.","checkedAt":"2026-11-03"},{"source":"ICB Instituut — Staatsbesluit van 22 juli 2025","url":"https://icb-instituut.com/staatsbesluit-van-22-juli-2025-t-u-v-artikel-18a-wet-loonbelasting-suriname/","kind":"SECONDARY","finding":"Aanpassing tariefschijven overwerk en verhoging vrijstelling vakantie-uitkeringen.","checkedAt":"2026-11-03"}]'::jsonb,'[{"date":"2026-11-03","previous":"Status: volgens S.B. 2025 no. 129 ingetrokken.","current":"Status: verhouding tot S.B. 2025 no. 129 niet vastgesteld (conflict).","reason":"Bij hercontrole geen bron gevonden die de intrekking bevestigt; S.B. 2025 no. 129 behandelt volgens ICB hetzelfde onderwerp."}]'::jsonb,NOW()) ON CONFLICT ("code") DO UPDATE SET "title"=EXCLUDED."title","publication"=EXCLUDED."publication","publishedAt"=EXCLUDED."publishedAt","effectiveFrom"=EXCLUDED."effectiveFrom","subject"=EXCLUDED."subject","articles"=EXCLUDED."articles","url"=EXCLUDED."url","verificationStatus"=EXCLUDED."verificationStatus","notes"=EXCLUDED."notes","article"=EXCLUDED."article","state"=EXCLUDED."state","summary"=EXCLUDED."summary","lastAmendment"=EXCLUDED."lastAmendment","lastCheckedAt"=EXCLUDED."lastCheckedAt","components"=EXCLUDED."components","evidence"=EXCLUDED."evidence","history"="LegalSource"."history" || EXCLUDED."history","updatedAt"=NOW();
INSERT INTO "LegalSource" ("code","title","publication","publishedAt","effectiveFrom","subject","articles","url","verificationStatus","notes","article","state","summary","lastAmendment","lastCheckedAt","components","evidence","history","updatedAt") VALUES ('SB-2025-129','Staatsbesluit van 29 oktober 2025 ter uitvoering van artikel 18a van de Wet Loonbelasting','S.B. 2025 no. 129','2025-10-31',NULL,'Verruiming tariefschijven loon uit overwerk en verhoging van het niet tot het loon behorende bedrag bij vakantie-uitkeringen','[]'::jsonb,'https://www.sris.sr/wp-content/uploads/2025/11/S.B.-2025-no.-129-STAATSBESLUIT-ter-uitvoering-van-artikel-18a-van-de-Wet-Loonbelasting.pdf','CONFLICT',NULL,'nog te bevestigen','TO_VERIFY','Gedateerd 29 oktober 2025, geplaatst in het Staatsblad op 31 oktober 2025. Onderwerp gelijk aan S.B. 2025 no. 101; inhoud (bedragen, ingangsdata) niet ingezien.',NULL,'2026-11-03','["Bijzondere beloningen (LB-BB)","Overwerk (LB-OT)"]'::jsonb,'[{"source":"ICB Instituut — tag Wet Loonbelasting","url":"https://icb-instituut.com/tag/wet-loonbelasting/","kind":"SECONDARY","finding":"Staatsbesluit van 29 oktober 2025 (art. 18a) op 31 oktober 2025 geplaatst als S.B. 2025 no. 129; onderwerp overwerkschijven en vakantie-uitkeringen.","checkedAt":"2026-11-03"}]'::jsonb,'[{"date":"2026-11-03","previous":"Trekt S.B. 2025 no. 101 in; overige inhoud niet geverifieerd. Publicatiedatum 29-10-2025.","current":"Onderwerp overwerkschijven en vakantie-uitkeringen; intrekking van no. 101 niet bevestigd. Besluit 29-10-2025, publicatie 31-10-2025.","reason":"Nieuwe secundaire bron over onderwerp en publicatiedatum; eerdere bewering over intrekking niet onderbouwd."}]'::jsonb,NOW()) ON CONFLICT ("code") DO UPDATE SET "title"=EXCLUDED."title","publication"=EXCLUDED."publication","publishedAt"=EXCLUDED."publishedAt","effectiveFrom"=EXCLUDED."effectiveFrom","subject"=EXCLUDED."subject","articles"=EXCLUDED."articles","url"=EXCLUDED."url","verificationStatus"=EXCLUDED."verificat