INSERT INTO "LegalSource" ("code","title","publication","publishedAt","effectiveFrom","subject","articles","url","verificationStatus","notes","article","state","summary","lastAmendment","lastCheckedAt","components","evidence","history","updatedAt") VALUES ('KB-2026-ONTWERP','Ontwerp-staatsbesluit vrijstelling kinderbijslag (art. 10 Wet Loonbelasting)','Ontwerp (april 2026) — geen Staatsbladnummer gevonden',NULL,NULL,'Verdubbeling vrijgestelde kinderbijslag: SRD 125 → SRD 250 per kind per maand; maximum SRD 500 → SRD 1.000','[]'::jsonb,NULL,'PENDING_VERIFICATION',NULL,'art. 10','TO_VERIFY','Alleen als ontwerp gemeld. Niet toegepast: ARA Payroll gebruikt de vastgestelde vrijstelling uit de actieve regelset tot een gepubliceerd staatsbesluit is geverifieerd.',NULL,'2026-11-03','["Kinderbijslag (vrijstelling)"]'::jsonb,'[{"source":"Dagblad Suriname — Kinderbijslag verdubbeld, maar kader blijft beperkt (20-04-2026)","url":"https://www.dbsuriname.com/2026/04/20/kinderbijslag-verdubbeld-maar-kader-blijft-beperkt/","kind":"SECONDARY","finding":"Ontwerp-staatsbesluit: vrijstelling SRD 250 per kind per maand, maximum SRD 1.000.","checkedAt":"2026-11-03"}]'::jsonb,'[]'::jsonb,NOW()) ON CONFLICT ("code") DO UPDATE SET "title"=EXCLUDED."title","publication"=EXCLUDED."publication","publishedAt"=EXCLUDED."publishedAt","effectiveFrom"=EXCLUDED."effectiveFrom","subject"=EXCLUDED."subject","articles"=EXCLUDED."articles","url"=EXCLUDED."url","verificationStatus"=EXCLUDED."verificationStatus","notes"=EXCLUDED."notes","article"=EXCLUDED."article","state"=EXCLUDED."state","summary"=EXCLUDED."summary","lastAmendment"=EXCLUDED."lastAmendment","lastCheckedAt"=EXCLUDED."lastCheckedAt","components"=EXCLUDED."components","evidence"=EXCLUDED."evidence","history"="LegalSource"."history" || EXCLUDED."history","updatedAt"=NOW();
INSERT INTO "LegalSource" ("code","title","publication","publishedAt","effectiveFrom","subject","articles","url","verificationStatus","notes","article","state","summary","lastAmendment","lastCheckedAt","components","evidence","history","updatedAt") VALUES ('WET-AOV','Wet Algemene Oudedagsvoorziening','Wet van 20 maart 1981 tot instelling van een Algemene Oudedagsvoorziening (zoals gewijzigd)','1981-03-20',NULL,'AOV-premie','[{"article":"—","summary":"Premie 4% van de heffingsgrondslag"},{"article":"—","summary":"Grondslag: zuiver inkomen (IB 1922) of, als loonbelasting verschuldigd is, het zuiver loon (Wet Loonbelasting)"},{"article":"—","summary":"Premieplichtig: ingezetene die de leeftijd van 60 jaar nog niet heeft bereikt; heffing o.a. door inhouding op het loon"}]'::jsonb,'https://belastingdienst.sr/wp-content/uploads/2024/10/Wet-AOV.pdf','PARTIALLY_VERIFIED','Aangifte loonbelasting en premie AOV is één gecombineerde maandaangifte. Verdeling werkgever/werknemer niet in de wettekst gevonden (ARA Payroll: 100% werknemer).','premieartikelen (nummering te bevestigen)','AMENDED','Premie 4% van de heffingsgrondslag (zuiver loon / zuiver inkomen). Premieplichtig: ingezetenen met loon of winst die de leeftijd van 60 jaar nog niet hebben bereikt. Heffing o.a. door inhouding op het loon; geen werkgeversdeel en geen franchise gevonden.',NULL,'2026-11-03','["AOV (werknemer)","AOV werkgeversdeel (0%)","Leeftijdsgrens 60 jaar"]'::jsonb,'[{"source":"Belastingdienst Suriname — Wet AOV (pdf, uittreksel)","url":"https://belastingdienst.sr/wp-content/uploads/2024/10/Wet-AOV.pdf","kind":"OFFICIAL_EXCERPT","finding":"Premie 4% van de heffingsgrondslag; premieplichtig tot 60 jaar; heffing door inhouding op het loon.","checkedAt":"2026-11-03"},{"source":"Dagblad Suriname — AOV is geen cadeautje van de regering (21-08-2026)","url":"https://www.dbsuriname.com/2026/08/21/aov-is-geen-cadeautje-van-de-regering/","kind":"SECONDARY","finding":"Bevestigt 4% van de heffingsgrondslag.","checkedAt":"2026-11-03"}]'::jsonb,'[]'::jsonb,NOW()) ON CONFLICT ("code") DO UPDATE SET "title"=EXCLUDED."title","publication"=EXCLUDED."publication","publishedAt"=EXCLUDED."publishedAt","effectiveFrom"=EXCLUDED."effectiveFrom","subject"=EXCLUDED."subject","articles"=EXCLUDED."articles","url"=EXCLUDED."url","verificationStatus"=EXCLUDED."verificationStatus","notes"=EXCLUDED."notes","article"=EXCLUDED."article","state"=EXCLUDED."state","summary"=EXCLUDED."summary","lastAmendment"=EXCLUDED."lastAmendment","lastCheckedAt"=EXCLUDED."lastCheckedAt","components"=EXCLUDED."components","evidence"=EXCLUDED."evidence","history"="LegalSource"."history" || EXCLUDED."history","updatedAt"=NOW();
INSERT INTO "LegalSource" ("code","title","publication","publishedAt","effectiveFrom","subject","articles","url","verificationStatus","notes","article","state","summary","lastAmendment","lastCheckedAt","components","evidence","history","updatedAt") VALUES ('SB-2019-64','Wet Arbeidsbescherming Gezin (bescherming moederschap)','S.B. 2019 no. 64','2019-06-10',NULL,'Zwangerschaps- en bevallingsverlof, vaderschapsverlof, adoptieverlof en het Fonds Voorzieningen Ouderschapsverlof','[{"article":"—","summary":"Zwangerschaps- en bevallingsverlof samen max. 16 weken (24 weken bij meerlingen van drie of meer); 4–6 weken vóór de bevalling"},{"article":"6","summary":"Adoptie van een kind jonger dan 18 maanden: 6 weken betaald verlof voor de adoptiemoeder"},{"article":"—","summary":"Vaderschapsverlof: 8 dagen betaald verlof, ingaand op de dag van de bevalling"},{"article":"—","summary":"Loondoorbetaling via het Fonds Voorzieningen Ouderschapsverlof (FVO)"}]'::jsonb,'https://www.dna.sr/media/3bjewn4q/sb_2019___64.pdf','PARTIALLY_VERIFIED','Ouderschapsverlof (zorgverlof na de geboorteperiode) is in deze wet niet gevonden en blijft bedrijfsbeleid. Adoptieverlof voor adoptievaders en kinderen vanaf 18 maanden niet bevestigd.','o.a. art. 6 (adoptieverlof); overige artikelnummers te bevestigen','IN_FORCE','Zwangerschaps- en bevallingsverlof samen 16 weken (4–6 weken vóór de bevalling), 24 weken bij drie- of meerlingen; vaderschapsverlof 8 dagen vanaf de dag van de bevalling; adoptieverlof 6 weken bij adoptie van een kind jonger dan 18 maanden. Volledig doorbetaald; het FVO zorgt voor de doorbetaling.',NULL,'2026-11-03','["LEV007 Zwangerschaps- en bevallingsverlof","LEV008 Vaderschapsverlof","LEV009 Adoptieverlof","FVO"]'::jsonb,'[{"source":"Overheid Suriname — Werkgevers verplicht tot 16 weken zwangerschaps- en bevallingsverlof","url":"https://gov.sr/werkgevers-verplicht-tot-16-weken-zwangerschaps-en-bevallingsverlof/","kind":"OFFICIAL_EXCERPT","finding":"16 weken, bij drie- of meerlingen 24 weken.","checkedAt":"2026-11-03"},{"source":"Overheid Suriname — Toelichting op Wet Arbeidsbescherming voor Gezin","url":"https://gov.sr/toelichting-op-wet-arbeidsbescherming-voor-gezin/","kind":"OFFICIAL_EXCERPT","finding":"Vaderschapsverlof 8 dagen betaald verlof; doorbetaling via het FVO.","checkedAt":"2026-11-03"},{"source":"DNA — S.B. 2019 no. 64 (uittreksel)","url":"https://www.dna.sr/media/3bjewn4q/sb_2019___64.pdf","kind":"OFFICIAL_EXCERPT","finding":"Art. 6: adoptie kind < 18 maanden — 6 weken betaald verlof voor de adoptiemoeder.","checkedAt":"2026-11-03"},{"source":"Starnieuws/SR Herald — Voortaan maximaal 24 weken verlof bij zwangerschap (2019)","url":"https://www.srherald.com/suriname/2019/04/12/voortaan-maximaal-24-weken-verlof-bij-zwangerschap/","kind":"SECONDARY","finding":"Vaderschapsverlof bij behandeling verruimd van 5 naar 8 dagen.","checkedAt":"2026-11-03"}]'::jsonb,'[{"date":"2026-11-03","previous":"Vaderschapsverlof: duur volgens bronnen 5, 7 of 8 dagen (conflict).","current":"Vaderschapsverlof: 8 dagen (gedeeltelijk geverifieerd).","reason":"Overheidspublicatie en parlementaire berichtgeving noemen 8 dagen (verruimd van oorspronkelijk voorgestelde 5)."},{"date":"2026-11-03","previous":"Loondoorbetaling via fonds (FVO); bijdrage volgens berichtgeving 1% van het brutoloon — niet geverifieerd.","current":"Premie FVO vastgelegd in afzonderlijke registervermelding FVO (grondslag: basisloon, niet brutoloon).","reason":"Officiële FVO- en overheidspublicaties noemen het basismaandloon exclusief toelagen en emolumenten als grondslag."}]'::jsonb,NOW()) ON CONFLICT ("code") DO UPDATE SET "title"=EXCLUDED."title","publication"=EXCLUDED."publication","publishedAt"=EXCLUDED."publishedAt","effectiveFrom"=EXCLUDED."effectiveFrom","subject"=EXCLUDED."subject","articles"=EXCLUDED."articles","url"=EXCLUDED."url","verificationStatus"=EXCLUDED."verificationStatus","notes"=EXCLUDED."notes","article"=EXCLUDED."article","state"=EXCLUDED."state","summary"=EXCLUDED."summary","lastAmendment"=EXCLUDED."lastAmendment","lastCheckedAt"=EXCLUDED."lastCheckedAt","components"=EXCLUDED."components","evidence"=EXCLUDED."evidence","history"="LegalSource"."history" || EXCLUDED."history","updatedAt"=NOW();
INSERT INTO "LegalSource" ("code","title","publication","publishedAt","effectiveFrom","subject","articles","url","verificationStatus","notes","article","state","summary","lastAmendment","lastCheckedAt","components","evidence","history","updatedAt") VALUES ('FVO','Fonds Voorzieningen Ouderschapsverlof — premie, afdracht en uitkeringen','Wet Arbeidsbescherming Gezin (S.B. 2019 no. 64) en uitvoeringsregels van het FVO',NULL,'2023-03-01','FVO-premie: 1% van het basismaandloon, verdeeld tussen werkgever (minimaal de helft) en werknemer (maximaal de helft)','[{"article":"—","summary":"Premie 1% van het basismaandloon (exclusief toelagen en emolumenten)"},{"article":"—","summary":"Werknemer maximaal 50%, werkgever minimaal 50% van de premie"},{"article":"—","summary":"Maandelijkse afdracht door de werkgever, uiterlijk de 14e van de volgende maand"}]'::jsonb,'https://fvo.sr/nl/faq','PARTIALLY_VERIFIED','Tegenstrijdigheden: (1) start inning 1 maart 2023 (overheid) of april 2023 (Celery); (2) verdeling ''gelijk'' (overheid/FVO) of ''werkgever mag alles dragen'' (Celery). Het premieartikel in de wettekst is niet ingezien. Daarom blijft de FVO-regeling inactief tot een beheerder de officiële grondslag heeft geverifieerd en de tarieven heeft goedgekeurd.','premieartikel S.B. 2019 no. 64 (nummer te bevestigen)','IN_FORCE','Totale premie 1% van het basismaandloon exclusief toelagen en emolumenten. Werknemersdeel maximaal 0,5%, werkgeversdeel minimaal 0,5%. De werkgever houdt het werknemersdeel bij elke loonbetaling in en draagt beide delen maandelijks af (uiterlijk de 14e van de volgende maand). Geen maximum gevonden. Uitkeringen pas na minimaal 3 maanden premiebetaling (niet voor werkgevers die vóór 1 juli 2023 geregistreerd waren).',NULL,'2026-11-03','["FVO-EE (werknemersaandeel)","FVO-ER (werkgeversaandeel)","DED012","ER007"]'::jsonb,'[{"source":"FVO — Veelgestelde vragen","url":"https://fvo.sr/nl/faq","kind":"OFFICIAL_EXCERPT","finding":"Premie berekend over het basismaandloon, exclusief toelagen en emolumenten; welke vergoedingen het FVO vergoedt.","checkedAt":"2026-11-03"},{"source":"Overheid Suriname — FVO","url":"https://gov.sr/fvo/","kind":"OFFICIAL_EXCERPT","finding":"Grondslag basissalaris exclusief emolumenten; werkgever minimaal en werknemer maximaal de helft van 1%.","checkedAt":"2026-11-03"},{"source":"Overheid Suriname — Registratieplicht voor doorbetaald ouderschapsverlof aangevangen","url":"https://gov.sr/registratieplicht-voor-doorbetaald-ouderschapsverlof-aangevangen/","kind":"OFFICIAL_EXCERPT","finding":"Registratie vóór 15 februari 2023; inning vanaf 1 maart 2023.","checkedAt":"2026-11-03"},{"source":"VSB — Stand van zaken ouderschapsverlofregeling","url":"https://vsbstia.org/?p=8108","kind":"SECONDARY","finding":"Werkgever en werknemer elk 0,5% van het brutoloon; afdracht maandelijks.","checkedAt":"2026-11-03"},{"source":"Celery — Fonds Voorzieningen Ouderschapsverlof (FVO)","url":"https://www.celerypayroll.com/blog/algemeen/suriname-fonds-voorzieningen-ouderschapsverlof-fvo/","kind":"SECONDARY","finding":"1% totaal, 0,5% werkgever en 0,5% werknemer; start april 2023; werkgever mag het volledige bedrag dragen.","checkedAt":"2026-11-03"}]'::jsonb,'[{"date":"2026-11-03","previous":"Percentage en verdeling werkgever/werknemer niet geverifieerd; berichtgeving noemt 1% van het brutoloon.","current":"1% van het basismaandloon (excl. toelagen en emolumenten); werknemer max. 0,5%, werkgever min. 0,5% — gedeeltelijk geverifieerd.","reason":"Officiële FVO- en overheidspublicaties noemen het basismaandloon; ''brutoloon'' komt alleen uit secundaire bronnen."}]'::jsonb,NOW()) ON CONFLICT ("code") DO UPDATE SET "title"=EXCLUDED."title","publication"=EXCLUDED."publication","publishedAt"=EXCLUDED."publishedAt","effectiveFrom"=EXCLUDED."effectiveFrom","subject"=EXCLUDED."subject","articles"=EXCLUDED."articles","url"=EXCLUDED."url","verificationStatus"=EXCLUDED."verificationStatus","notes"=EXCLUDED."notes","article"=EXCLUDED."article","state"=EXCLUDED."state","summary"=EXCLUDED."summary","lastAmendment"=EXCLUDED."lastAmendment","lastCheckedAt"=EXCLUDED."lastCheckedAt","components"=EXCLUDED."components","evidence"=EXCLUDED."evidence","history"="LegalSource"."history" || EXCLUDED."history","updatedAt"=NOW();
INSERT INTO "LegalSource" ("code","title","publication","publishedAt","effectiveFrom","subject","articles","url","verificationStatus","notes","article","state","summary","lastAmendment","lastCheckedAt","components","evidence","history","updatedAt") VALUES ('WAP-2014','Wet Algemeen Pensioen 2014','S.B. 2014 no. 113','2014-09-09','2014-12-09','Verplichte algemene pensioenvoorziening voor werknemers (Algemeen Pensioenfonds of gelijkwaardige regeling van de werkgever)','[{"article":"8 lid 2","summary":"Premie 2025: 8% van het brutoloon (volgens het Algemeen Pensioenfonds); premie 2026 niet gevonden"},{"article":"8 lid 6","summary":"Minimum- en maximumgrondslag bij staatsbesluit (zie S.B. 2023 no. 118)"},{"article":"—","summary":"Werkgever minimaal 50%, werknemer maximaal 50% van de premie"}]'::jsonb,'https://www.dna.sr/media/edbanrlx/wet_algemeen_pensioen_2014.pdf','PARTIALLY_VERIFIED','Nieuw opgenomen. Pensioen is daarmee een wettelijke verplichting (in ARA Payroll stond pensioen standaard als arbeidsvoorwaardelijk). Eigen pensioenregelingen van werkgevers kunnen afwijkende (gelijkwaardige) tarieven hebben.','art. 8 (premie), art. 7 (indexering)','AMENDED','Werkgevers moeten hun werknemers een pensioenregeling bieden (via het Algemeen Pensioenfonds of een aan de wet aangepaste eigen regeling). Werkgever betaalt minimaal 50%, werknemer maximaal 50% van de premie. Premie 2025 volgens het APF: 8% van het brutoloon (art. 8 lid 2). Pensioengrondslag sinds 1 januari 2023: minimaal SRD 2.250 en maximaal SRD 22.500 per maand.','S.B. 2023 no. 117 en no. 118','2026-11-03','["PENSION-EE","PENSION-ER","DED002","ER001","Pensioenpercentage arbeidsovereenkomst"]'::jsonb,'[{"source":"Algemeen Pensioenfonds — Veelgestelde vragen","url":"https://www.pensioen.sr/veelgestelde-vragen/","kind":"OFFICIAL_EXCERPT","finding":"Premie 2025: 8% van het brutoloon (art. 8 lid 2); werkgever minimaal 50%, werknemer maximaal 50%.","checkedAt":"2026-11-03"},{"source":"DNA — Wet Algemeen Pensioen 2014 (uittreksel)","url":"https://www.dna.sr/media/edbanrlx/wet_algemeen_pensioen_2014.pdf","kind":"OFFICIAL_EXCERPT","finding":"Werkgever past bestaande regeling aan of sluit zich aan bij de wet; pensioenrecht na minimaal 5 jaar premiebetaling.","checkedAt":"2026-11-03"},{"source":"Celery — What employers should know about the APF pension scheme","url":"https://www.celerypayroll.com/en/blog/general/suriname-what-employers-should-know-about-the-pension-scheme-of-the-algemeen-pensioenfonds-apf/","kind":"SECONDARY","finding":"2023: totaal 7% (3,5% / 3,5%).","checkedAt":"2026-11-03"},{"source":"Milliman — IFRS-waarderingen werkgevers Suriname","url":"https://www.milliman.com/nl-NL/insight/ifrs-waarderingen-werkgevers-suriname-impact-wet-algemeen-pensioen","kind":"SECONDARY","finding":"Werkgevers verplicht een minimale pensioenregeling te bieden; vermeldt een maximumsalaris van SRD 5.000 (verouderd).","checkedAt":"2026-11-03"}]'::jsonb,'[]'::jsonb,NOW()) ON CONFLICT ("code") DO UPDATE SET "title"=EXCLUDED."title","publication"=EXCLUDED."publication","publishedAt"=EXCLUDED."publishedAt","effectiveFrom"=EXCLUDED."effectiveFrom","subject"=EXCLUDED."subject","articles"=EXCLUDED."articles","url"=EXCLUDED."url","verificationStatus"=EXCLUDED."verificationStatus","notes"=EXCLUDED."notes","article"=EXCLUDED."article","state"=EXCLUDED."state","summary"=EXCLUDED."summary","lastAmendment"=EXCLUDED."lastAmendment","lastCheckedAt"=EXCLUDED."lastCheckedAt","components"=EXCLUDED."components","evidence"=EXCLUDED."evidence","history"="LegalSource"."history" || EXCLUDED."history","updatedAt"=NOW();
INSERT INTO "LegalSource" ("code","title","publication","publishedAt","effectiveFrom","subject","articles","url","verificationStatus","notes","article","state","summary","lastAmendment","lastCheckedAt","components","evidence","history","updatedAt") VALUES ('SB-2023-118','Staatsbesluit van 7 augustus 2023 ter uitvoering van artikel 8 lid 6 van de Wet Algemeen Pensioen 2014','S.B. 2023 no. 118','2023-08-07','2023-01-01','Minimum- en maximumgrondslag pensioenpremie','[{"article":"—","summary":"Minimum SRD 2.250 per maand; maximum SRD 22.500 per maand (SRD 270.000 per jaar)"}]'::jsonb,'https://www.celerypayroll.com/wp-content/uploads/2023/10/S.B.-2023-no.-118-STAATSBESLUIT-van-7-augustus-ter-uitvoering-van-artikel-8-lid-6-van-de-Wet-Algemeen-Pensioen-2014-S.B.-2014-no.-113.pdf','PARTIALLY_VERIFIED',NULL,'uitvoering art. 8 lid 6 WAP 2014','IN_FORCE','Minimumgrondslag SRD 2.250 per maand (was SRD 500); maximumgrondslag SRD 270.000 per jaar / SRD 22.500 per maand (was SRD 60.000 per jaar), terugwerkend tot 1 januari 2023.',NULL,'2026-11-03','["Pensioen: minimum- en maximumgrondslag"]'::jsonb,'[{"source":"Celery — Major changes pension scheme APF","url":"https://www.celerypayroll.com/en/blog/general/suriname-major-changes-pension-scheme-of-algemeen-pensioenfonds-apf/","kind":"SECONDARY","finding":"Minimum SRD 2.250 per maand, maximum SRD 270.000 per jaar, terugwerkend tot 1 januari 2023.","checkedAt":"2026-11-03"}]'::jsonb,'[]'::jsonb,NOW()) ON CONFLICT ("code") DO UPDATE SET "title"=EXCLUDED."title","publication"=EXCLUDED."publication","publishedAt"=EXCLUDED."publishedAt","effectiveFrom"=EXCLUDED."effectiveFrom","subject"=EXCLUDED."subject","articles"=EXCLUDED."articles","url"=EXCLUDED."url","verificationStatus"=EXCLUDED."verificationStatus","notes"=EXCLUDED."notes","article"=EXCLUDED."article","state"=EXCLUDED."state","summary"=EXCLUDED."summary","lastAmendment"=EXCLUDED."lastAmendment","lastCheckedAt"=EXCLUDED."lastCheckedAt","components"=EXCLUDED."components","evidence"=EXCLUDED."evidence","history"="LegalSource"."history" || EXCLUDED."history","updatedAt"=NOW();
INSERT INTO "LegalSource" ("code","title","publication","publishedAt","effectiveFrom","subject","articles","url","verificationStatus","notes","article","state","summary","lastAmendment","lastCheckedAt","components","evidence","history","updatedAt") VALUES ('WNBZ-2014','Wet Nationale Basiszorgverzekering','Wet Nationale Basiszorgverzekering (2014)',NULL,'2014-10-09','Verplichte basiszorgverzekering; werkgever verzekert iedere werknemer en betaalt minimaal 50% van de premie','[{"article":"—","summary":"Werkgever minimaal 50% van de premie; werknemersdeel ingehouden op het loon"},{"article":"—","summary":"Premie per leeftijdscategorie (vast bedrag); actuele bedragen niet bevestigd"}]'::jsonb,'https://www.basiszorg.sr/index.php/basiszorgverzekering-2/wetnationalebasiszorgverzekering/','PARTIALLY_VERIFIED','Bronnen geven tegenstrijdige premiebedragen. Stel de bedragen per medewerker (leeftijd) in op basis van de polis van de zorgverzekeraar.','werkgeversverplichtingen (nummering te bevestigen)','IN_FORCE','De werkgever sluit voor iedere werknemer een basiszorgverzekering af, betaalt minimaal 50% van de premie, spreekt de inhouding van het werknemersdeel af en draagt de premie tijdig af. Premie per leeftijdscategorie (vast bedrag, geen percentage); de actuele bedragen zijn niet bevestigd (2014: SRD 55 / 75 / 165 / 240).',NULL,'2026-11-03','["HEALTH-EE","HEALTH-ER","DED004","ER002"]'::jsonb,'[{"source":"Overheid Suriname — Basiszorgverzekering","url":"https://gov.sr/thema/basiszorgverzekering/","kind":"OFFICIAL_EXCERPT","finding":"Iedere werkgever is verplicht minimaal 50% van de premie te betalen.","checkedAt":"2026-11-03"},{"source":"Uitvoeringsorgaan Basiszorg — Wet Nationale Basiszorgverzekering","url":"https://www.basiszorg.sr/index.php/basiszorgverzekering-2/wetnationalebasiszorgverzekering/","kind":"OFFICIAL_EXCERPT","finding":"Premies per leeftijd: SRD 55 (0–16), 75 (17–20), 165 (21–59), 240 (60+) — stand 2014.","checkedAt":"2026-11-03"},{"source":"Vertrekklaar — Zorg in Suriname","url":"https://vertrekklaar.nl/kennis/zorg-in-suriname","kind":"SECONDARY","finding":"Noemt veel hogere maandpremies (bijv. SRD 785 voor 21–40 jaar) — tegenstrijdig.","checkedAt":"2026-11-03"}]'::jsonb,'[]'::jsonb,NOW()) ON CONFLICT ("code") DO UPDATE SET "title"=EXCLUDED."title","publication"=EXCLUDED."publication","publishedAt"=EXCLUDED."publishedAt","effectiveFrom"=EXCLUDED."effectiveFrom","subject"=EXCLUDED."subject","articles"=EXCLUDED."articles","url"=EXCLUDED."url","verificationStatus"=EXCLUDED."verificationStatus","notes"=EXCLUDED."notes","article"=EXCLUDED."article","state"=EXCLUDED."state","summary"=EXCLUDED."summary","lastAmendment"=EXCLUDED."lastAmendment","lastCheckedAt"=EXCLUDED."lastCheckedAt","components"=EXCLUDED."components","evidence"=EXCLUDED."evidence","history"="LegalSource"."history" || EXCLUDED."history","updatedAt"=NOW();
INSERT INTO "LegalSource" ("code","title","publication","publishedAt","effectiveFrom","subject","articles","url","verificationStatus","notes","article","state","summary","lastAmendment","lastCheckedAt","components","evidence","history","updatedAt") VALUES ('VACANTIEWET','Vakantiewet','Vakantiewet 1975 (zoals gewijzigd)',NULL,NULL,'Vakantiedagen en vakantietoelage','[]'::jsonb,'https://www.dna.sr/media/egnb5dhm/vakantiewet.pdf','PENDING_VERIFICATION','ARA Payroll berekent de vakantietoelage alleen zoals de werkgever die instelt (vast of percentage); geen wettelijk percentage toegepast.','nog te bevestigen','TO_VERIFY','Volgens een fragment van de wettekst is de werkgever verplicht over de betreffende periode een vakantietoelage uit te betalen; hoogte en voorwaarden niet bevestigd. Vakantiedagen: 12 per jaar, oplopend (maximum volgens secundaire bron 18).',NULL,'2026-11-03','["BON006 Vakantietoelage","Verlofsaldo jaarlijks verlof"]'::jsonb,'[{"source":"DNA — Vakantiewet (fragment)","url":"https://www.dna.sr/media/egnb5dhm/vakantiewet.pdf","kind":"OFFICIAL_EXCERPT","finding":"''… is de werkgever verplicht hem tenminste over die periode de vakantietoelage uit te betalen'' (fragment, context ontbreekt).","checkedAt":"2026-11-03"},{"source":"Doing Business Dutch Caribbean — Annual leave Suriname","url":"https://www.doingbusinessdutchcaribbean.com/suriname/employment-sur/annual-leave-sur/","kind":"SECONDARY","finding":"Vakantiedagen lopen op tot maximaal 18 per jaar.","checkedAt":"2026-11-03"}]'::jsonb,'[]'::jsonb,NOW()) ON CONFLICT ("code") DO UPDATE SET "title"=EXCLUDED."title","publication"=EXCLUDED."publication","publishedAt"=EXCLUDED."publishedAt","effectiveFrom"=EXCLUDED."effectiveFrom","subject"=EXCLUDED."subject","articles"=EXCLUDED."articles","url"=EXCLUDED."url","verificationStatus"=EXCLUDED."verificationStatus","notes"=EXCLUDED."notes","article"=EXCLUDED."article","state"=EXCLUDED."state","summary"=EXCLUDED."summary","lastAmendment"=EXCLUDED."lastAmendment","lastCheckedAt"=EXCLUDED."lastCheckedAt","components"=EXCLUDED."components","evidence"=EXCLUDED."evidence","history"="LegalSource"."history" || EXCLUDED."history","updatedAt"=NOW();
INSERT INTO "LegalSource" ("code","title","publication","publishedAt","effectiveFrom","subject","articles","url","verificationStatus","notes","article","state","summary","lastAmendment","lastCheckedAt","components","evidence","history","updatedAt") VALUES ('ARBEIDSWET-1963','Arbeidswet','Arbeidswet 1963 (zoals gewijzigd); Wet Werktijdenregeling 2019',NULL,NULL,'Arbeidstijden en overwerk','[]'::jsonb,'https://www.dna.sr/media/cwabf0np/arbeidswet.pdf','PENDING_VERIFICATION',NULL,'art. 64 e.v. (overwerk)','TO_VERIFY','Overwerkbepalingen vanaf art. 64; toeslagpercentages (150% / 200%) niet in de wettekst bevestigd. In ARA Payroll zijn de overwerkpercentages bedrijfsinstellingen (contract/cao).',NULL,'2026-11-03','["OT1 Overwerk 150%","OT2 Overwerk 200%"]'::jsonb,'[{"source":"Rivermate — Werktijden Suriname","url":"https://rivermate.com/nl/gidsen/suriname/werktijden","kind":"SECONDARY","finding":"Overwerk meestal 150% op weekdagen, hoger op weekenden en feestdagen — niet officieel.","checkedAt":"2026-11-03"}]'::jsonb,'[]'::jsonb,NOW()) ON CONFLICT ("code") DO UPDATE SET "title"=EXCLUDED."title","publication"=EXCLUDED."publication","publishedAt"=EXCLUDED."publishedAt","effectiveFrom"=EXCLUDED."effectiveFrom","subject"=EXCLUDED."subject","articles"=EXCLUDED."articles","url"=EXCLUDED."url","verificationStatus"=EXCLUDED."verificationStatus","notes"=EXCLUDED."notes","article"=EXCLUDED."article","state"=EXCLUDED."state","summary"=EXCLUDED."summary","lastAmendment"=EXCLUDED."lastAmendment","lastCheckedAt"=EXCLUDED."lastCheckedAt","components"=EXCLUDED."components","evidence"=EXCLUDED."evidence","history"="LegalSource"."history" || EXCLUDED."history","updatedAt"=NOW();

-- Default contribution schemes that were never configured: corrected statutory basis and references.
-- Only untouched defaults (no rates, never approved, original reference text) are changed.
UPDATE "ContributionScheme" SET "basis" = 'STATUTORY', "base" = 'GROSS_WAGE', "legalStatus" = 'PARTIALLY_VERIFIED',
  "legalReference" = 'Wet Algemeen Pensioen 2014 (S.B. 2014 no. 113) art. 8; S.B. 2023 no. 118 (minimum- en maximumgrondslag): werkgever minimaal 50% van de premie — percentage per regeling verifiëren (zie Wettelijke bronnen)'
WHERE "type" = 'PENSION' AND "approvedAt" IS NULL AND "employeeRateBp" = 0 AND "employerRateBp" = 0 AND "employeeAmount" = 0 AND "employerAmount" = 0
  AND "legalReference" = 'Pensioenreglement van de werkgever / het pensioenfonds';
UPDATE "ContributionScheme" SET "method" = 'FIXED', "legalStatus" = 'PARTIALLY_VERIFIED',
  "legalReference" = 'Wet Nationale Basiszorgverzekering (2014): werkgever verzekert iedere werknemer en betaalt minimaal 50% van de premie; premie per leeftijdscategorie (actuele bedragen niet geverifieerd — zie Wettelijke bronnen)'
WHERE "type" = 'HEALTH' AND "approvedAt" IS NULL AND "employeeRateBp" = 0 AND "employerRateBp" = 0 AND "employeeAmount" = 0 AND "employerAmount" = 0
  AND "legalReference" = 'Basiszorgverzekering — premie, grondslag en verdeling werkgever/werknemer niet geverifieerd';
UPDATE "ContributionScheme" SET "legalStatus" = 'PARTIALLY_VERIFIED',
  "legalReference" = 'Wet Arbeidsbescherming Gezin (S.B. 2019 no. 64) / Fonds Voorzieningen Ouderschapsverlof: volgens officiële publicaties 1% van het basismaandloon excl. toelagen en emolumenten, werknemer max. 50% — premieartikel niet geverifieerd (zie Wettelijke bronnen)'
WHERE "type" = 'FVO' AND "approvedAt" IS NULL AND "employeeRateBp" = 0 AND "employerRateBp" = 0 AND "employeeAmount" = 0 AND "employerAmount" = 0
  AND "legalReference" LIKE 'Fonds ouderschapsverlof (Wet Arbeidsbescherming Gezin)%';

-- Leave types: references updated after research (durations unchanged: 80 / 8 / 30 working days).
UPDATE "LeaveType" SET "legalStatus" = 'PARTIALLY_VERIFIED', "legalReference" = 'Wet Arbeidsbescherming Gezin, S.B. 2019 no. 64 — zwangerschaps- en bevallingsverlof samen 16 weken (4–6 weken vóór de bevalling), 24 weken bij drie- of meerlingen; doorbetaling via het FVO'
WHERE "category" = 'MATERNITY' AND "legalReference" = 'Wet Arbeidsbescherming Gezin, S.B. 2019 no. 64 — 16 weken (24 bij meerlingen van 3+)';
UPDATE "LeaveType" SET "legalStatus" = 'PARTIALLY_VERIFIED', "legalReference" = 'Wet Arbeidsbescherming Gezin, S.B. 2019 no. 64 — vaderschapsverlof 8 dagen vanaf de dag van de bevalling (eerder: bronnen noemden 5, 7 of 8 dagen)'
WHERE "category" = 'PATERNITY' AND "legalReference" = 'Wet Arbeidsbescherming Gezin, S.B. 2019 no. 64 — duur volgens bronnen 5, 7 of 8 dagen';
UPDATE "LeaveType" SET "legalStatus" = 'PARTIALLY_VERIFIED', "legalReference" = 'Wet Arbeidsbescherming Gezin, S.B. 2019 no. 64, art. 6 — 6 weken bij adoptie van een kind jonger dan 18 maanden (adoptiemoeder; adoptievader niet bevestigd)'
WHERE "category" = 'ADOPTION' AND "legalReference" = 'Wet Arbeidsbescherming Gezin, S.B. 2019 no. 64 — 6 weken (kind < 18 maanden)';

-- Library references.
UPDATE "ComponentLibrary" SET "legalStatus" = 'PARTIALLY_VERIFIED', "legalReference" = 'FVO (S.B. 2019 no. 64): 1% van het basismaandloon, werknemer max. 50% — premieartikel niet geverifieerd' WHERE "code" IN ('DED012', 'ER007');
UPDATE "ComponentLibrary" SET "legalReference" = 'Wet Algemeen Pensioen 2014 (S.B. 2014 no. 113) art. 8' WHERE "code" IN ('DED002', 'ER001');
UPDATE "ComponentLibrary" SET "legalStatus" = 'PARTIALLY_VERIFIED', "legalReference" = 'Wet Arbeidsbescherming Gezin, S.B. 2019 no. 64 — 8 dagen' WHERE "code" = 'LEV008';
UPDATE "ComponentLibrary" SET "legalStatus" = 'PARTIALLY_VERIFIED' WHERE "code" IN ('LEV007', 'LEV009');
